/* ============================================================================
 * TapMyCar  Patch  Tow company URL system (multi-driver, server-side)
 *
 * Replaces the localStorage-only tow operator flow with a server-side
 * model. Manager sets up once  shares one driver link  every driver
 * taps it once on their phone and is permanently linked.
 *
 * NEW manager flow:
 *   1) Manager opens /for-tow-companies.html
 *   2) Fills company name + phone + lot address + manager email
 *   3) Server creates a tow_companies record with a unique 6-char code
 *   4) Manager gets emailed the driver URL: tapmycar.io/join.html?co=AAA7X9
 *   5) Manager forwards link to drivers via WhatsApp/SMS/email
 *
 * NEW driver flow:
 *   1) Driver taps the manager's link
 *   2) /join.html sets an HttpOnly 1-year cookie (tmc_tow_co) on their phone
 *   3) Done. Driver never sets up anything else.
 *
 * NEW daily tow:
 *   1) Driver taps the TapMyCar sticker on a towed car
 *   2) contact.html  "I'm a tow operator"  /towing.html?tag=TMC-XXX
 *   3) /towing.html reads the cookie to identify the company server-side
 *   4) Plate auto-filled from the tag (Yes/No verify)
 *   5) Pick template + send  owner gets email + push
 *
 * Adds:
 *   /api/tow-company-create   manager creates company, emails URL
 *   /api/tow-join             driver taps URL  cookie set
 *   /api/tow-company-self     /towing.html asks "am I linked?"
 *   /public/for-tow-companies.html   manager setup form
 *   /public/join.html                driver onboarding "you're linked"
 *
 * Modifies:
 *   /api/tow-notify           reads cookie to identify company (server-trusted),
 *                             falls back to body for legacy clients
 *   /public/towing.html       cookie-based, no localStorage; clear "not
 *                             linked yet" state with instructions
 *
 * SQL migration (run FIRST in Supabase):
 *   patch-tow-companies-migration.sql  creates tow_companies table +
 *   adds tow_company_code column to tow_notifications.
 *
 * Run from project root:  node tapmycar-patch-tow-company-system.js
 * Safe to re-run.
 * ==========================================================================*/
'use strict';
const fs = require('fs');
const path = require('path');

const STAMP = new Date().toISOString().slice(0,16).replace(/[:T]/g,'-');
const BACKUP_DIR = 'backup-tow-company-system-' + STAMP;

const FILES = {"api/tow-company-create.js": "// TMC_TOW_COMPANY_CREATE: manager submits company info -> get unique code + URL.\nconst { createClient } = require('@supabase/supabase-js');\nconst { Resend } = require('resend');\nconst supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_KEY);\nconst resend   = new Resend(process.env.RESEND_API_KEY);\nconst { rateLimit, getClientIp } = require('./_rate-limit');\n\nconst ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';\nfunction generateCode(len) {\n  let c = '';\n  for (let i = 0; i < len; i++) c += ALPHABET[Math.floor(Math.random() * ALPHABET.length)];\n  return c;\n}\nfunction esc(s) { return String(s||'').replace(/[&<>\"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;' }[c])); }\n\nmodule.exports = async function handler(req, res) {\n  if (req.method !== 'POST') return res.status(405).json({ error: 'Method not allowed' });\n\n  const ip = getClientIp(req);\n  if (!await rateLimit(req, res, [{ key: 'tow-co-create:ip:' + ip, max: 3, windowSeconds: 3600 }])) return;\n\n  const b = req.body || {};\n  const company_name = String(b.company_name || '').trim().slice(0, 200);\n  const phone        = String(b.phone || '').trim().slice(0, 60);\n  const address      = String(b.address || '').trim().slice(0, 400);\n  const admin_email  = String(b.admin_email || '').trim().toLowerCase().slice(0, 200);\n\n  if (!company_name || !phone || !admin_email)\n    return res.status(400).json({ error: 'company_name, phone, and admin_email are required' });\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(admin_email))\n    return res.status(400).json({ error: 'Invalid email' });\n\n  // Generate unique 6-char code (~1B combinations, no confusing chars)\n  let code = '';\n  for (let attempt = 0; attempt < 10; attempt++) {\n    code = generateCode(6);\n    const { data: dupe } = await supabase\n      .from('tow_companies').select('id').eq('code', code).maybeSingle();\n    if (!dupe) break;\n    code = '';\n  }\n  if (!code) return res.status(500).json({ error: 'Could not generate unique code' });\n\n  const { data, error } = await supabase\n    .from('tow_companies')\n    .insert({ code, company_name, phone, address: address || null, admin_email, active: true })\n    .select('code')\n    .single();\n  if (error) return res.status(500).json({ error: 'Failed to create company' });\n\n  const driverUrl = 'https://tapmycar.io/join.html?co=' + code;\n\n  // Email manager\n  try {\n    const html =\n      '<div style=\"font-family:Inter,Arial,sans-serif;max-width:520px;margin:0 auto;padding:32px 22px;color:#111\">' +\n        '<div style=\"font-size:24px;font-weight:800;margin-bottom:4px\">TapMyCar<span style=\"color:#FF6B00\">.</span></div>' +\n        '<div style=\"font-size:12px;color:#6B7280;margin-bottom:22px\">For towing companies</div>' +\n        '<div style=\"background:#FFF7ED;border:1.5px solid #FED7AA;border-radius:14px;padding:18px;margin-bottom:18px\">' +\n          '<div style=\"font-size:11px;font-weight:800;color:#9A3412;text-transform:uppercase;letter-spacing:.06em;margin-bottom:6px\">Your team driver link</div>' +\n          '<div style=\"font-size:18px;font-weight:800;color:#7C2D12;line-height:1.3;margin-bottom:8px\">' + esc(company_name) + ' is set up</div>' +\n          '<div style=\"font-size:14px;color:#9A3412;line-height:1.6;margin-bottom:14px\">Share this link with every driver on your team. They tap it once on their phone, then every TapMyCar sticker they scan automatically notifies the car owner with your company info.</div>' +\n          '<div style=\"background:#fff;border:1px solid #FED7AA;border-radius:10px;padding:14px;font-family:monospace;font-size:14px;font-weight:700;color:#7C2D12;word-break:break-all;text-align:center\">' + esc(driverUrl) + '</div>' +\n        '</div>' +\n        '<div style=\"background:#EFF6FF;border:1px solid #BFDBFE;border-radius:12px;padding:14px;font-size:12px;color:#1E40AF;line-height:1.6\">' +\n          '<b>Save this email.</b> It is your record of the URL. If a driver leaves or the link gets shared too widely, email <a href=\"mailto:support@tapmycar.io\" style=\"color:#1E40AF\">support@tapmycar.io</a> and we will rotate the code.' +\n        '</div>' +\n        '<div style=\"font-size:11px;color:#9CA3AF;text-align:center;margin-top:22px\">Praman Tech LLC \\u00b7 Connecticut, USA</div>' +\n      '</div>';\n    await resend.emails.send({\n      from: 'TapMyCar <noreply@tapmycar.io>',\n      to: admin_email,\n      subject: 'Your TapMyCar driver link for ' + company_name,\n      html\n    });\n  } catch (e) { console.error('email failed:', e && e.message); }\n\n  return res.json({ ok: true, code: data.code, url: driverUrl, company_name: company_name });\n};\n", "api/tow-join.js": "// TMC_TOW_JOIN: driver taps the manager-provided link -> sets cookie linking\n// this device to the towing company. Cookie lives for 1 year.\nconst { createClient } = require('@supabase/supabase-js');\nconst supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_KEY);\nconst { rateLimit, getClientIp } = require('./_rate-limit');\n\nmodule.exports = async function handler(req, res) {\n  if (req.method !== 'GET') return res.status(405).json({ error: 'Method not allowed' });\n\n  const ip = getClientIp(req);\n  if (!await rateLimit(req, res, [{ key: 'tow-join:ip:' + ip, max: 50, windowSeconds: 3600 }])) return;\n\n  const code = String(req.query.co || '').trim().toUpperCase();\n  if (!code || !/^[A-Z2-9]{4,12}$/.test(code))\n    return res.status(400).json({ error: 'Invalid code' });\n\n  const { data, error } = await supabase\n    .from('tow_companies')\n    .select('code, company_name, phone, address')\n    .eq('code', code).eq('active', true).maybeSingle();\n  if (error || !data) return res.status(404).json({ error: 'Code not found or inactive' });\n\n  // Set device cookie: 1 year, HttpOnly + SameSite=Lax (Lax so NFC opens still send it)\n  const host = String(req.headers.host || '');\n  const isProd = !host.includes('localhost') && !host.includes('127.0.0.1');\n  const parts = ['tmc_tow_co=' + code, 'HttpOnly', 'SameSite=Lax', 'Path=/', 'Max-Age=31536000'];\n  if (isProd) parts.push('Secure');\n  res.setHeader('Set-Cookie', parts.join('; '));\n\n  return res.json({ ok: true, company_name: data.company_name, phone: data.phone, address: data.address || '' });\n};\n", "api/tow-company-self.js": "// TMC_TOW_COMPANY_SELF: returns the current device's linked company (if any).\n// Used by /towing.html on load to decide what to show.\nconst { createClient } = require('@supabase/supabase-js');\nconst supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_KEY);\n\nfunction readCookie(req, name) {\n  const header = req.headers && req.headers.cookie;\n  if (!header) return null;\n  const parts = header.split(';');\n  for (let i = 0; i < parts.length; i++) {\n    const eq = parts[i].indexOf('=');\n    if (eq === -1) continue;\n    if (parts[i].slice(0, eq).trim() === name) return parts[i].slice(eq + 1).trim();\n  }\n  return null;\n}\n\nmodule.exports = async function handler(req, res) {\n  if (req.method !== 'GET') return res.status(405).json({ error: 'Method not allowed' });\n\n  const code = String(readCookie(req, 'tmc_tow_co') || '').trim().toUpperCase();\n  if (!code) {\n    res.setHeader('Cache-Control', 'no-store');\n    return res.json({ ok: true, linked: false });\n  }\n\n  const { data, error } = await supabase\n    .from('tow_companies')\n    .select('code, company_name, phone, address')\n    .eq('code', code).eq('active', true).maybeSingle();\n\n  if (error || !data) {\n    // Stale or revoked cookie -> clear it so /towing.html doesn't loop\n    res.setHeader('Set-Cookie', 'tmc_tow_co=; HttpOnly; SameSite=Lax; Path=/; Max-Age=0');\n    res.setHeader('Cache-Control', 'no-store');\n    return res.json({ ok: true, linked: false, revoked: true });\n  }\n  res.setHeader('Cache-Control', 'no-store');\n  return res.json({\n    ok: true, linked: true,\n    code: data.code, company_name: data.company_name, phone: data.phone, address: data.address || ''\n  });\n};\n", "api/tow-notify.js": "// TMC_TOW_NOTIFY: tow operator submits a notification for a scanned tag.\n// V2 (TMC_TOW_NOTIFY_COOKIE): reads device cookie to identify the company\n// instead of trusting form body fields. Falls back to body fields if cookie\n// is missing (legacy localStorage clients).\nconst { Resend } = require('resend');\nconst { createClient } = require('@supabase/supabase-js');\nconst supabase = createClient(process.env.SUPABASE_URL, process.env.SUPABASE_SERVICE_KEY);\nconst resend   = new Resend(process.env.RESEND_API_KEY);\nconst { rateLimit, getClientIp } = require('./_rate-limit');\n\nfunction esc(s) { return String(s || '').replace(/[&<>\"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;' }[c])); }\n\nfunction readCookie(req, name) {\n  const header = req.headers && req.headers.cookie;\n  if (!header) return null;\n  const parts = header.split(';');\n  for (let i = 0; i < parts.length; i++) {\n    const eq = parts[i].indexOf('=');\n    if (eq === -1) continue;\n    if (parts[i].slice(0, eq).trim() === name) return parts[i].slice(eq + 1).trim();\n  }\n  return null;\n}\n\nmodule.exports = async function handler(req, res) {\n  if (req.method !== 'POST') return res.status(405).json({ error: 'Method not allowed' });\n\n  const ip = getClientIp(req);\n  if (!await rateLimit(req, res, [{ key: 'tow-notify:ip:' + ip, max: 5, windowSeconds: 3600 }])) return;\n\n  const b = req.body || {};\n  const token = String(b.token || '').trim();\n  const plate = String(b.license_plate || '').trim().toUpperCase().slice(0, 20);\n  const message = String(b.message || '').trim().slice(0, 1000);\n  if (!token || !plate) return res.status(400).json({ error: 'token and license_plate are required' });\n\n  // Per-tag rate limit (one car can't realistically be towed multiple times per hour)\n  if (!await rateLimit(req, res, [{ key: 'tow-notify:tag:' + token, max: 2, windowSeconds: 3600 }])) return;\n\n  // === Identify the tow company ===\n  // Preferred: cookie set by /api/tow-join (server-trusted)\n  // Fallback: body fields (legacy clients still using localStorage)\n  let towName = '', towPhone = '', towAddress = '', towCode = null;\n  const cookieCode = String(readCookie(req, 'tmc_tow_co') || '').trim().toUpperCase();\n  if (cookieCode) {\n    const { data } = await supabase\n      .from('tow_companies')\n      .select('code, company_name, phone, address')\n      .eq('code', cookieCode).eq('active', true).maybeSingle();\n    if (data) {\n      towCode = data.code;\n      towName = data.company_name;\n      towPhone = data.phone;\n      towAddress = data.address || '';\n    }\n  }\n  if (!towName) {\n    towName    = String(b.tow_company_name    || '').trim().slice(0, 200);\n    towPhone   = String(b.tow_company_phone   || '').trim().slice(0, 60);\n    towAddress = String(b.tow_company_address || '').trim().slice(0, 400);\n  }\n  if (!towName) return res.status(403).json({ error: 'Not linked to a towing company. Open your team driver link first.' });\n\n  // Lookup tag + owner\n  const { data: tag, error: tagErr } = await supabase\n    .from('tags')\n    .select('id, owner_id, vehicle_label, users!tags_owner_id_fkey(name, email, phone_verified)')\n    .eq('token', token).maybeSingle();\n  if (tagErr || !tag) return res.status(404).json({ error: 'Tag not found' });\n  if (!tag.users || !tag.users.email) return res.status(404).json({ error: 'Tag owner not reachable' });\n\n  // Persist\n  const { data: notif, error: nErr } = await supabase\n    .from('tow_notifications')\n    .insert({\n      tag_id: tag.id, owner_id: tag.owner_id,\n      license_plate: plate, tow_company_name: towName,\n      tow_company_phone: towPhone || null,\n      tow_company_address: towAddress || null,\n      tow_company_code: towCode,\n      message: message || null\n    })\n    .select('id, created_at').single();\n  if (nErr) return res.status(500).json({ error: 'Could not save notification' });\n\n  // Increment counter on the company (best effort)\n  if (towCode) {\n    supabase.rpc('increment_tow_count', { p_code: towCode }).then(() => {}, () => {});\n  }\n\n  const ownerName = tag.users.name || 'there';\n  const vehicle   = tag.vehicle_label || 'your vehicle';\n\n  // Email the owner\n  try {\n    const phoneRow = towPhone ? '<div style=\"margin-top:8px\"><b>Phone:</b> <a href=\"tel:' + esc(towPhone) + '\" style=\"color:#FF6B00;text-decoration:none\">' + esc(towPhone) + '</a></div>' : '';\n    const addrRow  = towAddress ? '<div style=\"margin-top:8px\"><b>Where to collect:</b><br>' + esc(towAddress).replace(/\\n/g,'<br>') + '</div>' : '';\n    const msgRow   = message ? '<div style=\"margin-top:14px;padding:12px;background:#FFF;border-radius:10px;font-style:italic;color:#374151\"><b style=\"font-style:normal;color:#7C2D12\">Note from the operator:</b><br>' + esc(message).replace(/\\n/g,'<br>') + '</div>' : '';\n    const html =\n      '<div style=\"font-family:Inter,Arial,sans-serif;max-width:520px;margin:0 auto;padding:32px 22px;color:#111\">' +\n        '<div style=\"font-size:24px;font-weight:800;margin-bottom:4px\">TapMyCar<span style=\"color:#FF6B00\">.</span></div>' +\n        '<div style=\"font-size:12px;color:#6B7280;margin-bottom:22px\">Privacy for you. Safety for your car.</div>' +\n        '<div style=\"background:#FFF7ED;border:1.5px solid #FED7AA;border-radius:14px;padding:18px;margin-bottom:18px\">' +\n          '<div style=\"font-size:11px;font-weight:800;color:#9A3412;text-transform:uppercase;letter-spacing:.06em;margin-bottom:6px\">Tow notification</div>' +\n          '<div style=\"font-size:18px;font-weight:800;color:#7C2D12;line-height:1.3;margin-bottom:8px\">Your car may have been towed.</div>' +\n          '<div style=\"font-size:14px;color:#9A3412;line-height:1.6\">Hi ' + esc(ownerName) + ',<br>A towing company scanned your TapMyCar sticker on <b>' + esc(vehicle) + '</b> (plate <b>' + esc(plate) + '</b>) and sent you this notification.</div>' +\n        '</div>' +\n        '<div style=\"background:#F9FAFB;border:1px solid #E5E7EB;border-radius:14px;padding:18px;font-size:14px;line-height:1.6;color:#111\">' +\n          '<div style=\"font-size:11px;font-weight:700;color:#6B7280;text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px\">Towing company details</div>' +\n          '<div><b>Company:</b> ' + esc(towName) + '</div>' + phoneRow + addrRow + msgRow +\n        '</div>' +\n        '<div style=\"background:#EFF6FF;border:1px solid #BFDBFE;border-radius:12px;padding:14px;font-size:12px;color:#1E40AF;line-height:1.6;margin-top:18px\">' +\n          '<b>Heads up:</b> this message came from a tow operator who scanned your sticker. Verify the company and call them directly using the number above before driving to any address.' +\n        '</div>' +\n        '<a href=\"https://tapmycar.io/my-tows.html\" style=\"display:block;background:#FF6B00;color:#fff;font-weight:800;font-size:14px;padding:14px 0;border-radius:12px;text-align:center;text-decoration:none;margin-top:18px\">View all tow notifications</a>' +\n      '</div>';\n    await resend.emails.send({\n      from: 'TapMyCar <noreply@tapmycar.io>',\n      to: tag.users.email,\n      subject: 'Tow alert: ' + towName + ' has your car (' + plate + ')',\n      html\n    });\n  } catch (e) { console.error('tow email failed:', e && e.message); }\n\n  // Push (best-effort)\n  try {\n    const webpush = require('web-push');\n    webpush.setVapidDetails(process.env.VAPID_EMAIL, process.env.VAPID_PUBLIC_KEY, process.env.VAPID_PRIVATE_KEY);\n    const { data: subs } = await supabase.from('push_subscriptions').select('*').eq('user_id', tag.owner_id);\n    if (subs && subs.length) {\n      const payload = JSON.stringify({ title: 'Tow alert  ' + towName, body: 'Your car (' + plate + ') was towed. Tap to view.', url: '/my-tows.html' });\n      for (const sub of subs) {\n        try {\n          await webpush.sendNotification({ endpoint: sub.endpoint, keys: { p256dh: sub.p256dh, auth: sub.auth } }, payload);\n        } catch (err) {\n          if (err.statusCode === 410) await supabase.from('push_subscriptions').delete().eq('endpoint', sub.endpoint);\n        }\n      }\n    }\n  } catch (e) { console.error('tow push failed:', e && e.message); }\n\n  return res.json({ ok: true, id: notif.id });\n};\n", "public/for-tow-companies.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<!-- TMC_TOW_COMPANY_SETUP -->\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<meta name=\"theme-color\" content=\"#FF6B00\">\n<title>Set up your towing company  TapMyCar</title>\n<meta name=\"description\" content=\"Set up your towing company on TapMyCar in 60 seconds. Every driver scans a sticker, the owner is notified instantly.\">\n<link rel=\"icon\" href=\"/favicon.ico\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<link rel=\"manifest\" href=\"/manifest.json\">\n<link rel=\"stylesheet\" href=\"/app.css\">\n<style>\n.ft { max-width: 560px; margin: 0 auto; padding: 22px 16px 80px; }\n.ft-hdr { display: flex; align-items: center; justify-content: space-between; margin-bottom: 22px; }\n.ft-eyebrow { display: inline-block; background: #FFF7ED; border: 1px solid #FED7AA; color: #9A3412; font-size: 10px; font-weight: 800; padding: 5px 11px; border-radius: 99px; letter-spacing: .05em; margin-bottom: 12px; }\n.ft-h1 { font-size: 28px; font-weight: 800; letter-spacing: -.5px; color: #111; margin: 0 0 8px; line-height: 1.15; }\n.ft-sub { font-size: 14px; color: #6B7280; line-height: 1.6; margin: 0 0 26px; }\n.ft-bullets { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin: 0 0 26px; }\n.ft-bullet { background: #FFF7ED; border: 1px solid #FED7AA; border-radius: 13px; padding: 14px; }\n.ft-bullet h4 { font-size: 13px; font-weight: 800; color: #7C2D12; margin: 0 0 4px; }\n.ft-bullet p { font-size: 11px; color: #9A3412; line-height: 1.55; margin: 0; }\n.ft-card { background: #fff; border: 1px solid #E5E7EB; border-radius: 16px; padding: 22px; }\n.ft-card h3 { font-size: 16px; font-weight: 800; color: #111; margin: 0 0 4px; }\n.ft-card .intro { font-size: 12px; color: #6B7280; margin: 0 0 18px; line-height: 1.55; }\n.ft-row { margin: 0 0 14px; }\n.ft-label { display: block; font-size: 11px; font-weight: 700; color: #6B7280; text-transform: uppercase; letter-spacing: .04em; margin: 0 0 6px; }\n.ft-input, .ft-textarea {\n  width: 100%; padding: 12px 14px; font-size: 14px;\n  border: 1.5px solid #E5E7EB; border-radius: 11px;\n  background: #fff; color: #111; font-family: inherit;\n  -webkit-appearance: none; appearance: none; box-sizing: border-box;\n  transition: border-color .2s ease, box-shadow .2s ease;\n}\n.ft-input:focus, .ft-textarea:focus { outline: none; border-color: #FF6B00; box-shadow: 0 0 0 4px rgba(255,107,0,.1); }\n.ft-textarea { resize: vertical; min-height: 70px; line-height: 1.5; }\n.ft-submit {\n  width: 100%; background: #FF6B00; color: #fff;\n  font-size: 15px; font-weight: 800; padding: 15px 0;\n  border: 0; border-radius: 13px; cursor: pointer;\n  margin-top: 10px; font-family: inherit;\n  box-shadow: 0 8px 22px rgba(255,107,0,.35);\n}\n.ft-submit:active { transform: translateY(2px); }\n.ft-submit:disabled { opacity: .55; cursor: not-allowed; }\n.ft-err { font-size: 12px; color: #DC2626; margin: 10px 0 0; min-height: 18px; }\n.ft-fineprint { font-size: 11px; color: #9CA3AF; line-height: 1.55; margin: 14px 0 0; }\n.ft-success { display: none; background: linear-gradient(135deg, #FFF7ED 0%, #FFE4CC 100%); border: 1px solid #FED7AA; border-radius: 16px; padding: 24px 22px; }\n.ft-success h3 { font-size: 22px; font-weight: 800; color: #7C2D12; margin: 0 0 6px; }\n.ft-success .lead { font-size: 13px; color: #9A3412; line-height: 1.6; margin: 0 0 18px; }\n.ft-url-box { background: #fff; border: 1.5px solid #FED7AA; border-radius: 12px; padding: 14px; font-family: monospace; font-size: 13px; font-weight: 700; color: #7C2D12; word-break: break-all; text-align: center; margin: 0 0 14px; }\n.ft-actions { display: flex; gap: 8px; flex-wrap: wrap; }\n.ft-action { flex: 1; min-width: 140px; background: #fff; color: #7C2D12; font-size: 12px; font-weight: 700; padding: 11px 14px; border: 1.5px solid #FED7AA; border-radius: 10px; cursor: pointer; font-family: inherit; text-align: center; }\n.ft-action:active { background: #FED7AA; }\n.ft-howto { background: #fff; border: 1px solid #FED7AA; border-radius: 12px; padding: 14px; margin: 18px 0 0; }\n.ft-howto h4 { font-size: 11px; font-weight: 800; color: #9A3412; text-transform: uppercase; letter-spacing: .05em; margin: 0 0 10px; }\n.ft-howto ol { margin: 0; padding-left: 20px; font-size: 12px; color: #7C2D12; line-height: 1.7; }\n</style>\n</head>\n<body class=\"wide-page\">\n<div class=\"ft\">\n  <div class=\"ft-hdr\">\n    <a href=\"/\" aria-label=\"TapMyCar\"><img src=\"/logo.png\" alt=\"TapMyCar\" style=\"height:42px;width:auto;display:block\"></a>\n    <a href=\"javascript:void(0)\" onclick=\"tmcSmartBack('/')\" class=\"back-link\" style=\"margin:0\">\\u2190 Back</a>\n  </div>\n\n  <div class=\"ft-eyebrow\">For towing companies</div>\n  <h1 class=\"ft-h1\">Notify owners the moment you tow their car.</h1>\n  <p class=\"ft-sub\">Set up once. Share one link with your drivers. Every TapMyCar sticker they scan auto-sends your company info to the car owner. No app to install, no signup for drivers.</p>\n\n  <div class=\"ft-bullets\">\n    <div class=\"ft-bullet\"><h4>5-second tows</h4><p>Driver scans sticker, picks template, hits send. Done.</p></div>\n    <div class=\"ft-bullet\"><h4>One setup, all drivers</h4><p>Share one link with your whole team.</p></div>\n    <div class=\"ft-bullet\"><h4>Owner gets details</h4><p>Email + push with your name, phone, lot.</p></div>\n    <div class=\"ft-bullet\"><h4>Fewer angry calls</h4><p>Owners know where the car is in seconds.</p></div>\n  </div>\n\n  <div id=\"ft-form-wrap\" class=\"ft-card\">\n    <h3>Set up your company</h3>\n    <p class=\"intro\">Takes 60 seconds. You'll get a link by email to share with every driver on your team.</p>\n\n    <div class=\"ft-row\"><label class=\"ft-label\" for=\"ft-co\">Company name *</label><input class=\"ft-input\" id=\"ft-co\" maxlength=\"200\" required></div>\n    <div class=\"ft-row\"><label class=\"ft-label\" for=\"ft-phone\">Company phone (the one owners will call) *</label><input class=\"ft-input\" type=\"tel\" id=\"ft-phone\" maxlength=\"60\" required placeholder=\"(555) 555-1234\"></div>\n    <div class=\"ft-row\"><label class=\"ft-label\" for=\"ft-addr\">Lot address (where owners pick up cars)</label><textarea class=\"ft-textarea\" id=\"ft-addr\" maxlength=\"400\" placeholder=\"359 Lasalle St, Springfield CT 06000\"></textarea></div>\n    <div class=\"ft-row\"><label class=\"ft-label\" for=\"ft-email\">Your email (we send you the driver link) *</label><input class=\"ft-input\" type=\"email\" id=\"ft-email\" maxlength=\"200\" required placeholder=\"manager@yourtowing.com\"></div>\n\n    <button type=\"button\" class=\"ft-submit\" id=\"ft-submit-btn\" onclick=\"ftSubmit()\">Get my driver link</button>\n    <div class=\"ft-err\" id=\"ft-err\"></div>\n    <p class=\"ft-fineprint\">Need to revoke or rotate the link later? Email <a href=\"mailto:support@tapmycar.io\" style=\"color:#FF6B00;text-decoration:none\">support@tapmycar.io</a>.</p>\n  </div>\n\n  <div id=\"ft-success\" class=\"ft-success\">\n    <h3>\\u2713 You're set up</h3>\n    <p class=\"lead\"><strong id=\"ft-success-name\"></strong> is now connected to TapMyCar. We also emailed this link to you.</p>\n    <div class=\"ft-label\" style=\"color:#9A3412\">Driver link  share with every driver</div>\n    <div class=\"ft-url-box\" id=\"ft-url-box\"></div>\n    <div class=\"ft-actions\">\n      <button type=\"button\" class=\"ft-action\" onclick=\"ftCopyUrl()\" id=\"ft-copy-btn\">Copy link</button>\n      <a class=\"ft-action\" id=\"ft-share-link\" style=\"text-decoration:none\" href=\"#\">Share</a>\n      <a class=\"ft-action\" id=\"ft-whatsapp-link\" style=\"text-decoration:none\" target=\"_blank\" href=\"#\">WhatsApp</a>\n    </div>\n    <div class=\"ft-howto\">\n      <h4>How drivers use it</h4>\n      <ol>\n        <li>You forward the link above to every driver (WhatsApp, SMS, email)</li>\n        <li>Each driver taps it once on their phone</li>\n        <li>From then on, scanning any TapMyCar sticker they tow will instantly notify the owner with your details</li>\n      </ol>\n    </div>\n  </div>\n</div>\n\n<script>\nwindow.tmcSmartBack = function (fallback) {\n  fallback = fallback || '/';\n  try {\n    if (document.referrer) {\n      var ref = new URL(document.referrer);\n      if (ref.origin === window.location.origin) {\n        var here = window.location.pathname.replace(/\\/+$/, '');\n        var refPath = ref.pathname.replace(/\\/+$/, '');\n        if (refPath !== here) { window.history.back(); return; }\n      }\n    }\n  } catch (e) {}\n  window.location.href = fallback;\n};\n\nwindow.ftSubmit = async function () {\n  var btn = document.getElementById('ft-submit-btn');\n  var err = document.getElementById('ft-err');\n  err.textContent = '';\n\n  var company  = document.getElementById('ft-co').value.trim();\n  var phone    = document.getElementById('ft-phone').value.trim();\n  var address  = document.getElementById('ft-addr').value.trim();\n  var email    = document.getElementById('ft-email').value.trim();\n\n  if (!company || !phone || !email) { err.textContent = 'Company name, phone, and email are required.'; return; }\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email)) { err.textContent = 'Please enter a valid email.'; return; }\n\n  btn.disabled = true; btn.textContent = 'Setting up\\u2026';\n  try {\n    var res = await fetch('/api/tow-company-create', {\n      method: 'POST', headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify({ company_name: company, phone: phone, address: address, admin_email: email })\n    });\n    var data = await res.json();\n    if (!res.ok || !data.ok) throw new Error(data.error || 'Something went wrong');\n\n    document.getElementById('ft-form-wrap').style.display = 'none';\n    document.getElementById('ft-success-name').textContent = data.company_name || company;\n    document.getElementById('ft-url-box').textContent = data.url;\n    document.getElementById('ft-share-link').href = data.url;\n    var waText = encodeURIComponent('Open this link once on your phone to set up TapMyCar tow alerts: ' + data.url);\n    document.getElementById('ft-whatsapp-link').href = 'https://wa.me/?text=' + waText;\n    document.getElementById('ft-success').style.display = 'block';\n    window.scrollTo({ top: 0, behavior: 'smooth' });\n  } catch (e) {\n    err.textContent = e.message || 'Network error. Try again.';\n    btn.disabled = false; btn.textContent = 'Get my driver link';\n  }\n};\n\nwindow.ftCopyUrl = function () {\n  var url = document.getElementById('ft-url-box').textContent;\n  var btn = document.getElementById('ft-copy-btn');\n  try {\n    navigator.clipboard.writeText(url).then(function () {\n      btn.textContent = '\\u2713 Copied';\n      setTimeout(function () { btn.textContent = 'Copy link'; }, 2000);\n    });\n  } catch (e) {\n    var ta = document.createElement('textarea');\n    ta.value = url; document.body.appendChild(ta);\n    ta.select(); document.execCommand('copy');\n    document.body.removeChild(ta);\n    btn.textContent = '\\u2713 Copied';\n    setTimeout(function () { btn.textContent = 'Copy link'; }, 2000);\n  }\n};\n</script>\n</body>\n</html>\n", "public/join.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<!-- TMC_TOW_JOIN_PAGE -->\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<meta name=\"theme-color\" content=\"#FF6B00\">\n<title>Linking your phone  TapMyCar</title>\n<meta name=\"robots\" content=\"noindex\">\n<link rel=\"icon\" href=\"/favicon.ico\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<link rel=\"stylesheet\" href=\"/app.css\">\n<style>\n.jn { max-width: 480px; margin: 0 auto; padding: 26px 18px 80px; min-height: 100vh; display: flex; flex-direction: column; }\n.jn-hdr { display: flex; align-items: center; justify-content: space-between; margin-bottom: 30px; }\n.jn-eyebrow { display: inline-block; background: #FFF7ED; border: 1px solid #FED7AA; color: #9A3412; font-size: 10px; font-weight: 800; padding: 5px 11px; border-radius: 99px; letter-spacing: .05em; }\n.jn-body { flex: 1; display: flex; flex-direction: column; align-items: center; text-align: center; padding-top: 20px; }\n.jn-spinner { width: 56px; height: 56px; border: 4px solid #FED7AA; border-top-color: #FF6B00; border-radius: 50%; animation: jnspin 0.9s linear infinite; margin-bottom: 18px; }\n@keyframes jnspin { to { transform: rotate(360deg); } }\n.jn-state { width: 100%; display: none; }\n.jn-state.show { display: block; }\n.jn-ic { width: 84px; height: 84px; border-radius: 50%; display: flex; align-items: center; justify-content: center; margin: 0 auto 18px; }\n.jn-ic.ok { background: linear-gradient(135deg, #FFF7ED, #FFE4CC); box-shadow: 0 12px 30px rgba(255,107,0,.25); }\n.jn-ic.bad { background: #FEF2F2; }\n.jn-ic svg { width: 38px; height: 38px; fill: none; stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; }\n.jn-ic.ok svg { stroke: #FF6B00; }\n.jn-ic.bad svg { stroke: #DC2626; }\n.jn-h1 { font-size: 28px; font-weight: 800; letter-spacing: -.5px; color: #111; margin: 0 0 8px; line-height: 1.15; }\n.jn-co { font-size: 24px; font-weight: 900; color: #FF6B00; margin: 0 0 18px; }\n.jn-p { font-size: 14px; color: #6B7280; line-height: 1.6; margin: 0 0 22px; max-width: 360px; }\n.jn-howto { background: #FFF7ED; border: 1px solid #FED7AA; border-radius: 14px; padding: 16px; margin: 0 0 22px; text-align: left; }\n.jn-howto h4 { font-size: 11px; font-weight: 800; color: #9A3412; text-transform: uppercase; letter-spacing: .05em; margin: 0 0 10px; }\n.jn-howto ol { margin: 0; padding-left: 20px; font-size: 12px; color: #7C2D12; line-height: 1.75; }\n.jn-cta { background: #FF6B00; color: #fff; font-size: 15px; font-weight: 800; padding: 14px 28px; border: 0; border-radius: 12px; text-decoration: none; cursor: pointer; box-shadow: 0 8px 22px rgba(255,107,0,.35); font-family: inherit; display: inline-block; }\n.jn-cta:active { transform: translateY(2px); }\n.jn-err-detail { font-size: 12px; color: #DC2626; margin: 10px 0; }\n</style>\n</head>\n<body class=\"wide-page\">\n<div class=\"jn\">\n  <div class=\"jn-hdr\">\n    <a href=\"/\" aria-label=\"TapMyCar\"><img src=\"/logo.png\" alt=\"TapMyCar\" style=\"height:42px;width:auto;display:block\"></a>\n    <div class=\"jn-eyebrow\">FOR TOW DRIVERS</div>\n  </div>\n\n  <div class=\"jn-body\">\n    <div id=\"jn-loading\">\n      <div class=\"jn-spinner\"></div>\n      <div style=\"font-size:13px;color:#6B7280\">Linking this phone\\u2026</div>\n    </div>\n\n    <div id=\"jn-success\" class=\"jn-state\">\n      <div class=\"jn-ic ok\"><svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n      <h1 class=\"jn-h1\">You\\u2019re linked.</h1>\n      <div class=\"jn-co\" id=\"jn-co-name\"></div>\n      <p class=\"jn-p\">From now on, just tap any TapMyCar sticker on a car you tow. The owner will be notified instantly with this company's contact info.</p>\n\n      <div class=\"jn-howto\">\n        <h4>What happens next</h4>\n        <ol>\n          <li>You tow a car with a TapMyCar sticker</li>\n          <li>Tap your phone on the sticker (or scan the QR code)</li>\n          <li>Pick a template, hit Send. Owner gets notified in seconds.</li>\n        </ol>\n      </div>\n\n      <a href=\"/\" class=\"jn-cta\">Got it</a>\n    </div>\n\n    <div id=\"jn-error\" class=\"jn-state\">\n      <div class=\"jn-ic bad\"><svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg></div>\n      <h1 class=\"jn-h1\">This link doesn\\u2019t work</h1>\n      <p class=\"jn-p\" id=\"jn-err-msg\">The link your manager shared with you is either expired or was revoked. Ask them for the latest one.</p>\n      <a href=\"/for-tow-companies.html\" class=\"jn-cta\">Set up a new company</a>\n    </div>\n  </div>\n</div>\n\n<script>\n(function () {\n  var co = '';\n  try {\n    var u = new URL(location.href);\n    co = u.searchParams.get('co') || '';\n  } catch (e) {}\n  if (!co) {\n    document.getElementById('jn-loading').style.display = 'none';\n    document.getElementById('jn-err-msg').textContent = 'No company code in the link. Make sure you tapped the full link your manager sent you.';\n    document.getElementById('jn-error').classList.add('show');\n    return;\n  }\n  fetch('/api/tow-join?co=' + encodeURIComponent(co), { credentials: 'include' })\n    .then(function (r) { return r.json().then(function (d) { return { ok: r.ok, d: d }; }); })\n    .then(function (resp) {\n      document.getElementById('jn-loading').style.display = 'none';\n      if (!resp.ok || !resp.d.ok) {\n        document.getElementById('jn-err-msg').textContent = (resp.d && resp.d.error) || 'Link not valid.';\n        document.getElementById('jn-error').classList.add('show');\n        return;\n      }\n      document.getElementById('jn-co-name').textContent = resp.d.company_name;\n      document.getElementById('jn-success').classList.add('show');\n    })\n    .catch(function () {\n      document.getElementById('jn-loading').style.display = 'none';\n      document.getElementById('jn-err-msg').textContent = 'Network error. Check your connection and try the link again.';\n      document.getElementById('jn-error').classList.add('show');\n    });\n})();\n</script>\n</body>\n</html>\n", "public/towing.html": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<!-- TMC_TOW_OPERATOR_PAGE TMC_TOW_COOKIE_V2 -->\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no\">\n<meta name=\"theme-color\" content=\"#FF6B00\">\n<title>Send tow alert  TapMyCar</title>\n<meta name=\"robots\" content=\"noindex\">\n<link rel=\"icon\" href=\"/favicon.ico\">\n<link rel=\"apple-touch-icon\" href=\"/apple-touch-icon.png\">\n<link rel=\"stylesheet\" href=\"/app.css\">\n<style>\n.tw { max-width: 480px; margin: 0 auto; padding: 22px 16px 220px; min-height: 100vh; }\n.tw-hdr { display: flex; align-items: center; justify-content: space-between; margin-bottom: 18px; }\n.tw-h1 { font-size: 24px; font-weight: 800; color: #111; letter-spacing: -.5px; margin: 0 0 6px; }\n.tw-sub { font-size: 13px; color: #6B7280; line-height: 1.55; margin: 0 0 22px; }\n\n.tw-loading { text-align: center; padding: 60px 18px; color: #9CA3AF; font-size: 13px; }\n.tw-spinner { width: 36px; height: 36px; border: 3px solid #FED7AA; border-top-color: #FF6B00; border-radius: 50%; animation: twspin 0.9s linear infinite; margin: 0 auto 14px; }\n@keyframes twspin { to { transform: rotate(360deg); } }\n\n.tw-state { display: none; }\n.tw-state.show { display: block; }\n\n/* NOT LINKED state */\n.tw-nolink-ic { width: 84px; height: 84px; border-radius: 50%; background: #FEF3C7; display: flex; align-items: center; justify-content: center; margin: 30px auto 18px; }\n.tw-nolink-ic svg { width: 38px; height: 38px; fill: none; stroke: #92400E; stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }\n.tw-nolink-h1 { font-size: 24px; font-weight: 800; color: #111; text-align: center; margin: 0 0 10px; }\n.tw-nolink-p { font-size: 13px; color: #6B7280; line-height: 1.6; margin: 0 0 22px; text-align: center; }\n.tw-nolink-card { background: #FEF3C7; border: 1px solid #FCD34D; border-radius: 14px; padding: 16px; margin: 0 0 18px; }\n.tw-nolink-card h4 { font-size: 11px; font-weight: 800; color: #92400E; text-transform: uppercase; letter-spacing: .05em; margin: 0 0 10px; }\n.tw-nolink-card ol { margin: 0; padding-left: 20px; font-size: 12px; color: #78350F; line-height: 1.75; }\n.tw-nolink-actions { display: flex; flex-direction: column; gap: 10px; }\n.tw-action-primary { background: #FF6B00; color: #fff; font-size: 14px; font-weight: 800; padding: 14px 0; border-radius: 12px; text-align: center; text-decoration: none; box-shadow: 0 6px 18px rgba(255,107,0,.3); }\n.tw-action-ghost { background: #fff; color: #6B7280; font-size: 13px; font-weight: 600; padding: 12px 0; border-radius: 12px; text-align: center; text-decoration: none; border: 1px solid #E5E7EB; }\n\n/* LINKED state form */\n.tw-card { background: #fff; border: 1px solid #E5E7EB; border-radius: 14px; padding: 16px; margin-bottom: 14px; }\n.tw-label { display: block; font-size: 11px; font-weight: 700; color: #6B7280; text-transform: uppercase; letter-spacing: .04em; margin: 0 0 6px; }\n.tw-input, .tw-textarea { width: 100%; padding: 13px 14px; font-size: 16px; font-weight: 600; border: 1.5px solid #E5E7EB; border-radius: 11px; background: #fff; color: #111; font-family: inherit; -webkit-appearance: none; appearance: none; box-sizing: border-box; letter-spacing: .03em; }\n.tw-input:focus, .tw-textarea:focus { outline: none; border-color: #FF6B00; box-shadow: 0 0 0 4px rgba(255,107,0,.1); }\n.tw-input:disabled { background: #F9FAFB; color: #111; cursor: not-allowed; }\n.tw-textarea { font-size: 14px; font-weight: 400; resize: vertical; min-height: 80px; line-height: 1.5; letter-spacing: normal; }\n.tw-plate { text-align: center; font-size: 22px; font-weight: 800; letter-spacing: .12em; text-transform: uppercase; }\n.tw-templates { display: flex; flex-wrap: wrap; gap: 6px; margin: 8px 0 6px; }\n.tw-template { background: #FFF7ED; color: #9A3412; font-size: 11px; font-weight: 700; padding: 6px 12px; border-radius: 99px; border: 1px solid #FED7AA; cursor: pointer; font-family: inherit; }\n.tw-template:active { background: #FED7AA; }\n.tw-from-card { background: linear-gradient(135deg, #FFF7ED 0%, #FFE4CC 100%); border: 1px solid #FED7AA; border-radius: 14px; padding: 14px 16px; margin-bottom: 14px; }\n.tw-from-l { font-size: 11px; font-weight: 700; color: #7C2D12; text-transform: uppercase; letter-spacing: .04em; margin-bottom: 2px; }\n.tw-from-name { font-size: 16px; font-weight: 800; color: #7C2D12; }\n.tw-from-meta { font-size: 11px; color: #9A3412; margin-top: 4px; line-height: 1.4; }\n.tw-bar { position: fixed; left: 0; right: 0; bottom: 0; background: #fff; border-top: 1px solid #E5E7EB; padding: 14px 16px calc(14px + env(safe-area-inset-bottom)) 16px; box-shadow: 0 -8px 24px rgba(0,0,0,.06); z-index: 50; }\n.tw-bar-inner { max-width: 480px; margin: 0 auto; }\n.tw-send { width: 100%; background: #FF6B00; color: #fff; font-size: 16px; font-weight: 800; padding: 16px 0; border: 0; border-radius: 13px; cursor: pointer; box-shadow: 0 8px 22px rgba(255,107,0,.4); font-family: inherit; }\n.tw-send:active { transform: translateY(2px); box-shadow: 0 3px 10px rgba(255,107,0,.3); }\n.tw-send:disabled { opacity: .55; cursor: not-allowed; }\n.tw-err { font-size: 12px; color: #DC2626; margin: 10px 0 0; text-align: center; min-height: 18px; }\n.tw-help { font-size: 11px; color: #9CA3AF; margin: 6px 0 0; line-height: 1.5; }\n.tw-no-tag { background: #FEF3C7; border: 1px solid #FCD34D; border-radius: 10px; padding: 10px 12px; font-size: 11px; color: #92400E; line-height: 1.5; margin: 8px 0 0; }\n.tw-verify { background: #FFF7ED; border: 1.5px solid #FED7AA; border-radius: 12px; padding: 12px 14px; margin: 10px 0; }\n.tw-verify-q { font-size: 12px; font-weight: 700; color: #7C2D12; margin-bottom: 4px; }\n.tw-verify-d { font-size: 11px; color: #9A3412; line-height: 1.5; margin-bottom: 10px; }\n.tw-verify-row { display: flex; gap: 8px; }\n.tw-verify-yes { flex: 1; background: #16A34A; color: #fff; font-size: 12px; font-weight: 800; padding: 9px 0; border: 0; border-radius: 9px; cursor: pointer; font-family: inherit; display: flex; align-items: center; justify-content: center; gap: 6px; }\n.tw-verify-no { flex: 1; background: #fff; color: #7C2D12; font-size: 12px; font-weight: 700; padding: 9px 0; border: 1px solid #FED7AA; border-radius: 9px; cursor: pointer; font-family: inherit; }\n.tw-verify.confirmed { background: #F0FDF4; border-color: #BBF7D0; padding: 8px 12px; }\n.tw-verify.confirmed .tw-verify-q,\n.tw-verify.confirmed .tw-verify-d,\n.tw-verify.confirmed .tw-verify-row { display: none; }\n.tw-verify.confirmed::before { content: \" Plate confirmed\"; display: block; font-size: 12px; font-weight: 700; color: #166534; }\n\n.tw-ok { text-align: center; padding: 30px 18px; }\n.tw-ok-ic { width: 64px; height: 64px; border-radius: 50%; background: #DCFCE7; display: flex; align-items: center; justify-content: center; margin: 0 auto 16px; }\n.tw-ok-ic svg { width: 32px; height: 32px; stroke: #16A34A; fill: none; stroke-width: 3; stroke-linecap: round; }\n.tw-ok h2 { font-size: 22px; font-weight: 800; color: #166534; margin: 0 0 6px; }\n.tw-ok p { font-size: 13px; color: #15803D; line-height: 1.55; margin: 0; }\n</style>\n</head>\n<body class=\"wide-page\">\n<div class=\"tw\">\n  <div class=\"tw-hdr\">\n    <a href=\"/\" aria-label=\"TapMyCar\"><img src=\"/logo.png\" alt=\"TapMyCar\" style=\"height:38px;width:auto;display:block\"></a>\n    <div style=\"font-size:10px;font-weight:800;color:#9A3412;background:#FFF7ED;border:1px solid #FED7AA;padding:5px 11px;border-radius:99px;letter-spacing:.05em\">FOR TOW DRIVERS</div>\n  </div>\n\n  <!-- LOADING -->\n  <div id=\"tw-loading\" class=\"tw-loading\">\n    <div class=\"tw-spinner\"></div>\n    Checking your link\\u2026\n  </div>\n\n  <!-- NOT LINKED state -->\n  <div id=\"tw-nolink\" class=\"tw-state\">\n    <div class=\"tw-nolink-ic\"><svg viewBox=\"0 0 24 24\"><path d=\"M9 12 l2 2 l4 -4\"/><circle cx=\"12\" cy=\"12\" r=\"10\"/></svg></div>\n    <h1 class=\"tw-nolink-h1\">This phone isn\\u2019t linked yet</h1>\n    <p class=\"tw-nolink-p\">Before you can send tow alerts, your manager needs to share your team's driver link with you.</p>\n    <div class=\"tw-nolink-card\">\n      <h4>What to do</h4>\n      <ol>\n        <li>Ask your manager for your team's TapMyCar driver link</li>\n        <li>Open the link once on this phone</li>\n        <li>Come back here  every TapMyCar sticker you scan will work automatically</li>\n      </ol>\n    </div>\n    <div class=\"tw-nolink-actions\">\n      <a class=\"tw-action-primary\" href=\"/for-tow-companies.html\">I'm the manager  set up our company</a>\n      <a class=\"tw-action-ghost\" href=\"/\">Back to TapMyCar</a>\n    </div>\n  </div>\n\n  <!-- LINKED state: notification form -->\n  <div id=\"tw-form\" class=\"tw-state\">\n    <h1 class=\"tw-h1\">Notify the owner</h1>\n    <p class=\"tw-sub\">5 seconds. Pick a plate, pick a template, send.</p>\n\n    <div class=\"tw-from-card\">\n      <div class=\"tw-from-l\">Sending as</div>\n      <div class=\"tw-from-name\" id=\"tw-from-name\"></div>\n      <div class=\"tw-from-meta\" id=\"tw-from-meta\"></div>\n    </div>\n\n    <div class=\"tw-card\">\n      <label class=\"tw-label\" for=\"tw-plate\">Vehicle license plate *</label>\n      <input class=\"tw-input tw-plate\" id=\"tw-plate\" maxlength=\"20\" autocomplete=\"off\" autocapitalize=\"characters\" placeholder=\"ABC 1234\">\n\n      <div class=\"tw-verify\" id=\"tw-verify\" style=\"display:none\">\n        <div class=\"tw-verify-q\">Plate read from the sticker  is it correct?</div>\n        <div class=\"tw-verify-d\">We pre-filled it from the TapMyCar tag. If it's wrong (paper plate, mismatch), tap No and type the actual plate.</div>\n        <div class=\"tw-verify-row\">\n          <button class=\"tw-verify-yes\" type=\"button\" onclick=\"twVerifyPlate(true)\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"3\" stroke-linecap=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg>Yes</button>\n          <button class=\"tw-verify-no\" type=\"button\" onclick=\"twVerifyPlate(false)\">No, edit</button>\n        </div>\n      </div>\n\n      <div class=\"tw-help\" id=\"tw-plate-help\">Type the plate exactly as printed on the car.</div>\n      <div class=\"tw-no-tag\" id=\"tw-no-tag\" style=\"display:none\">No sticker scanned. Tap a TapMyCar sticker first, or type the plate manually.</div>\n    </div>\n\n    <div class=\"tw-card\">\n      <label class=\"tw-label\">Pick a template</label>\n      <div class=\"tw-templates\">\n        <button type=\"button\" class=\"tw-template\" onclick=\"twSetTemplate('Towed to our lot. Please call us to arrange pickup.')\">Towed to our lot</button>\n        <button type=\"button\" class=\"tw-template\" onclick=\"twSetTemplate('Roadside assistance was provided.')\">Roadside assist</button>\n        <button type=\"button\" class=\"tw-template\" onclick=\"twSetTemplate('Vehicle was parked illegally and has been relocated.')\">Parked illegally</button>\n        <button type=\"button\" class=\"tw-template\" onclick=\"twSetTemplate('Vehicle blocked access. We had to move it.')\">Blocking access</button>\n      </div>\n      <label class=\"tw-label\" for=\"tw-msg\" style=\"margin-top:10px\">Custom note (optional)</label>\n      <textarea class=\"tw-textarea\" id=\"tw-msg\" maxlength=\"1000\" placeholder=\"Anything the owner should know...\"></textarea>\n    </div>\n  </div>\n\n  <!-- SUCCESS state -->\n  <div id=\"tw-ok\" class=\"tw-state tw-ok\">\n    <div class=\"tw-ok-ic\"><svg viewBox=\"0 0 24 24\"><polyline points=\"20 6 9 17 4 12\"/></svg></div>\n    <h2>Owner notified</h2>\n    <p>The vehicle owner has been emailed and notified. Thanks for using TapMyCar to keep drivers informed.</p>\n    <button class=\"tw-send\" style=\"margin-top:24px;max-width:280px\" onclick=\"twNew()\">Send another</button>\n  </div>\n</div>\n\n<div class=\"tw-bar\" id=\"tw-bar\" style=\"display:none\">\n  <div class=\"tw-bar-inner\">\n    <button class=\"tw-send\" id=\"tw-send-btn\" onclick=\"twSend()\">Send tow alert</button>\n    <div class=\"tw-err\" id=\"tw-send-err\"></div>\n  </div>\n</div>\n\n<script>\n(function () {\n  var token = '';\n  try {\n    var u = new URL(location.href);\n    token = u.searchParams.get('tag') || u.searchParams.get('t') || u.searchParams.get('token') || '';\n    if (!token) {\n      var parts = location.pathname.split('/').filter(Boolean);\n      if (parts.length >= 2 && parts[0].toLowerCase() === 'tag') token = parts[1];\n    }\n  } catch (e) {}\n\n  function show(id) {\n    ['tw-loading','tw-nolink','tw-form','tw-ok','tw-bar'].forEach(function (x) {\n      var el = document.getElementById(x);\n      if (!el) return;\n      if (x === id || (id === 'tw-form' && x === 'tw-bar')) {\n        if (x === 'tw-loading') el.style.display = 'block';\n        else el.classList.add('show');\n        if (x === 'tw-bar') el.style.display = 'block';\n      } else {\n        if (x === 'tw-loading') el.style.display = 'none';\n        else el.classList.remove('show');\n        if (x === 'tw-bar' && id !== 'tw-form') el.style.display = 'none';\n      }\n    });\n  }\n\n  function init() {\n    fetch('/api/tow-company-self', { credentials: 'include' })\n      .then(function (r) { return r.json(); })\n      .then(function (d) {\n        if (!d.ok || !d.linked) { show('tw-nolink'); return; }\n        document.getElementById('tw-from-name').textContent = d.company_name;\n        var meta = (d.phone || '') + (d.address ? '  ' + d.address.split('\\n')[0] : '');\n        document.getElementById('tw-from-meta').textContent = meta;\n        show('tw-form');\n        if (token) autofillFromTag();\n        else {\n          document.getElementById('tw-no-tag').style.display = 'block';\n          document.getElementById('tw-plate-help').style.display = 'none';\n        }\n      })\n      .catch(function () { show('tw-nolink'); });\n  }\n\n  function autofillFromTag() {\n    fetch('/api/get-tag?token=' + encodeURIComponent(token))\n      .then(function (r) { return r.json(); })\n      .then(function (d) {\n        var plate = (d && d.tag && d.tag.license_plate) ? String(d.tag.license_plate).toUpperCase().trim() : '';\n        if (!plate) return;\n        var input = document.getElementById('tw-plate');\n        input.value = plate; input.disabled = true;\n        document.getElementById('tw-verify').style.display = 'block';\n        document.getElementById('tw-plate-help').style.display = 'none';\n      })\n      .catch(function () {});\n  }\n\n  window.twVerifyPlate = function (yes) {\n    var input = document.getElementById('tw-plate');\n    var verify = document.getElementById('tw-verify');\n    if (yes) { input.disabled = true; verify.classList.add('confirmed'); }\n    else {\n      input.disabled = false; input.focus(); input.select();\n      verify.style.display = 'none';\n      document.getElementById('tw-plate-help').style.display = 'block';\n      document.getElementById('tw-plate-help').textContent = 'Type the correct plate as printed on the car.';\n    }\n  };\n\n  window.twSetTemplate = function (t) { document.getElementById('tw-msg').value = t; };\n  window.twNew = function () {\n    document.getElementById('tw-plate').value = '';\n    document.getElementById('tw-plate').disabled = false;\n    document.getElementById('tw-verify').style.display = 'none';\n    document.getElementById('tw-verify').classList.remove('confirmed');\n    document.getElementById('tw-msg').value = '';\n    show('tw-form');\n    if (token) autofillFromTag();\n    window.scrollTo({ top: 0, behavior: 'smooth' });\n  };\n\n  window.twSend = async function () {\n    var btn = document.getElementById('tw-send-btn');\n    var err = document.getElementById('tw-send-err');\n    var plate = document.getElementById('tw-plate').value.trim().toUpperCase();\n    var msg = document.getElementById('tw-msg').value.trim();\n    err.textContent = '';\n    if (!token) { err.textContent = 'No sticker scanned. Tap a TapMyCar sticker first.'; return; }\n    if (!plate || plate.length < 2) { err.textContent = 'Enter the license plate.'; return; }\n    btn.disabled = true; btn.textContent = 'Sending\\u2026';\n    try {\n      var res = await fetch('/api/tow-notify', {\n        method: 'POST', headers: { 'Content-Type': 'application/json' },\n        credentials: 'include',\n        body: JSON.stringify({ token: token, license_plate: plate, message: msg })\n      });\n      var data = await res.json();\n      if (!res.ok || !data.ok) throw new Error(data.error || 'Send failed');\n      show('tw-ok');\n      window.scrollTo({ top: 0, behavior: 'smooth' });\n    } catch (e) {\n      err.textContent = e.message || 'Network error. Try again.';\n      btn.disabled = false; btn.textContent = 'Send tow alert';\n    }\n  };\n\n  init();\n})();\n</script>\n</body>\n</html>\n"};

const MARKERS = {"api/tow-company-create.js": "TMC_TOW_COMPANY_CREATE", "api/tow-join.js": "TMC_TOW_JOIN", "api/tow-company-self.js": "TMC_TOW_COMPANY_SELF", "api/tow-notify.js": "TMC_TOW_NOTIFY_COOKIE", "public/for-tow-companies.html": "TMC_TOW_COMPANY_SETUP", "public/join.html": "TMC_TOW_JOIN_PAGE", "public/towing.html": "TMC_TOW_COOKIE_V2"};

let touched = 0;
for (const fp of Object.keys(FILES)) {
  const cur = fs.existsSync(fp) ? fs.readFileSync(fp, 'utf8') : '';
  if (cur.indexOf(MARKERS[fp]) !== -1) { console.log(fp + ': skip (already patched)'); continue; }
  fs.mkdirSync(path.join(BACKUP_DIR, path.dirname(fp)), { recursive: true });
  if (fs.existsSync(fp)) fs.copyFileSync(fp, path.join(BACKUP_DIR, fp));
  fs.writeFileSync(fp, FILES[fp], 'utf8');
  if (fp.endsWith('.js')) {
    try { require('child_process').execSync('node --check "' + fp + '"', { stdio: 'pipe' }); }
    catch (e) { throw new Error(fp + ': node --check failed: ' + String(e.stderr || e.message)); }
  }
  console.log(fp + ': written');
  touched++;
}

console.log('');
if (touched === 0) {
  console.log('Nothing to do  already patched.');
} else {
  console.log('Done. ' + touched + ' file(s) written. Backups in ' + BACKUP_DIR + '/');
  console.log('');
  console.log('FIRST (if not already done): in Supabase SQL editor, run');
  console.log('  patch-tow-companies-migration.sql');
  console.log('');
  console.log('NEXT STEPS:');
  console.log('  git add -A');
  console.log('  git commit -m "Tow company URL system: manager setup, driver join, cookie-based notify"');
  console.log('  git push');
  console.log('');
  console.log('TEST after ~60s (incognito):');
  console.log('  1. tapmycar.io/for-tow-companies.html  fill form  submit');
  console.log('     -> success screen with copy/share, manager email arrives');
  console.log('  2. Open the driver URL  /join.html  -> "You\'re linked" screen');
  console.log('  3. Open a real tag URL  tap "I am a tow operator"');
  console.log('  4. /towing.html shows your company at the top, plate auto-filled');
  console.log('  5. Pick template + send  owner gets email + push');
  console.log('  6. In a different incognito (no cookie)  open /towing.html');
  console.log('     -> "This phone is not linked yet" screen');
}
